#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"

[[ ! -e .env.docker ]] || {
  echo ".env.docker already exists; refusing to overwrite it" >&2
  exit 1
}
command -v openssl >/dev/null 2>&1 || { echo "openssl is required" >&2; exit 1; }

umask 077
api_key="$(openssl rand -hex 32)"
cat > .env.docker <<EOF
# Generated by scripts/prepare_docker_env.sh; keep mode 0600.
MOSS_HOST=127.0.0.1
MOSS_PORT=8002
MOSS_TRUSTED_SUBNETS=
MOSS_LOCAL_ONLY=true
MOSS_VLLM_URL=http://127.0.0.1:8001
MOSS_MODEL=OpenMOSS-Team/MOSS-Image-SFT
VLLM_API_KEY=$api_key
MOSS_ONLY_MODE=true
MOSS_OFFLINE_MODE=true
MOSS_MAX_PIXELS=auto
MOSS_MAX_QUEUE=1
MOSS_GPU_PROFILE=8gb-turing
VLLM_MODE=native
VLLM_HOST=127.0.0.1
VLLM_PORT=8001
CUDA_VISIBLE_DEVICES=0
VLLM_DTYPE=float16
MOSS_ALLOW_FP16_EXPERIMENTAL=true
MOSS_VLLM_DIFFUSION_OFFLOAD_CONFIG='{"mode":"layer","components":["dit","text_encoder"],"layer_options":{"dit":{"weight_transfer":"rank-local"},"text_encoder":{"weight_transfer":"rank-local"}},"pin_memory":true}'
MOSS_CONTAINER_UID=$(id -u)
MOSS_CONTAINER_GID=$(id -g)
EOF
chmod 0600 .env.docker
echo "Created loopback-only .env.docker; the local 8GB GPU worker remains on 127.0.0.1:8001."
